const items = $input.all();
const results = [];

for (const item of items) {
  const raw = item.json;

  // Buscar la transaccion en multiples ubicaciones posibles
  const tx = raw.data?.transaction
    || raw.body?.data?.transaction
    || raw.transaction
    || raw.body?.transaction
    || {};

  // Buscar sent_at en multiples ubicaciones
  const sentAtRaw = raw.sent_at || raw.body?.sent_at || '';

  const transactionId = tx.id || '';
  const reference = tx.reference || '';
  const status = tx.status || 'UNKNOWN';
  const amountInCents = tx.amount_in_cents || 0;
  const customerEmail = tx.customer_email || '';
  const paymentMethod = tx.payment_method_type || '';
  const currency = tx.currency || 'COP';
  const sentAt = sentAtRaw;

  // Formatear monto: centavos a pesos colombianos
  const amountPesos = amountInCents / 100;
  const amountFormatted = '$' + amountPesos.toLocaleString('es-CO');

  // Extraer celular del reference (formato: PF-{celular}-{timestamp})
  let customerPhone = '';
  const refParts = reference.split('-');
  if (refParts.length >= 3 && refParts[0] === 'PF') {
    customerPhone = refParts[1];
  }

  // Mapear status a espanol + emoji
  const statusMap = {
    'APPROVED': { label: 'APROBADO \u2705', emoji: '\u2705', verb: 'Aprobado' },
    'DECLINED': { label: 'RECHAZADO \u274C', emoji: '\u274C', verb: 'Rechazado' },
    'PENDING': { label: 'PENDIENTE \u23F3', emoji: '\u23F3', verb: 'Pendiente' },
    'VOIDED': { label: 'ANULADO \uD83D\uDEAB', emoji: '\uD83D\uDEAB', verb: 'Anulado' },
    'ERROR': { label: 'ERROR \u26A0\uFE0F', emoji: '\u26A0\uFE0F', verb: 'Error' }
  };

  const statusInfo = statusMap[status] || { label: status, emoji: '\u2753', verb: status };

  // Generar asunto del correo
  const emailSubject = `${statusInfo.emoji} Pago ${statusInfo.verb} - ${reference}`;

  // Generar cuerpo HTML del correo
  const emailBody = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
  <div style="background: #1C1B19; padding: 20px; text-align: center;">
    <h1 style="color: #FCD462; margin: 0;">Palacio Fitness</h1>
    <p style="color: #CECECE; margin: 5px 0 0;">Notificaci\u00f3n de Pago</p>
  </div>
  <div style="padding: 20px; background: #f9f9f9;">
    <h2 style="color: #333;">${statusInfo.emoji} Pago ${statusInfo.verb}</h2>
    <table style="width: 100%; border-collapse: collapse; margin: 15px 0;">
      <tr style="border-bottom: 1px solid #ddd;">
        <td style="padding: 10px; font-weight: bold; color: #555;">Referencia</td>
        <td style="padding: 10px;">${reference}</td>
      </tr>
      <tr style="border-bottom: 1px solid #ddd;">
        <td style="padding: 10px; font-weight: bold; color: #555;">Monto</td>
        <td style="padding: 10px; font-size: 18px; font-weight: bold;">${amountFormatted}</td>
      </tr>
      <tr style="border-bottom: 1px solid #ddd;">
        <td style="padding: 10px; font-weight: bold; color: #555;">Estado</td>
        <td style="padding: 10px;">${statusInfo.label}</td>
      </tr>
      <tr style="border-bottom: 1px solid #ddd;">
        <td style="padding: 10px; font-weight: bold; color: #555;">Email cliente</td>
        <td style="padding: 10px;">${customerEmail}</td>
      </tr>
      <tr style="border-bottom: 1px solid #ddd;">
        <td style="padding: 10px; font-weight: bold; color: #555;">Celular</td>
        <td style="padding: 10px;">${customerPhone || 'No disponible'}</td>
      </tr>
      <tr style="border-bottom: 1px solid #ddd;">
        <td style="padding: 10px; font-weight: bold; color: #555;">M\u00e9todo de pago</td>
        <td style="padding: 10px;">${paymentMethod}</td>
      </tr>
      <tr style="border-bottom: 1px solid #ddd;">
        <td style="padding: 10px; font-weight: bold; color: #555;">ID Transacci\u00f3n</td>
        <td style="padding: 10px; font-size: 12px;">${transactionId}</td>
      </tr>
      <tr>
        <td style="padding: 10px; font-weight: bold; color: #555;">Fecha</td>
        <td style="padding: 10px;">${sentAt ? new Date(sentAt).toLocaleString('es-CO', { timeZone: 'America/Bogota' }) : 'N/A'}</td>
      </tr>
    </table>
  </div>
  <div style="background: #1C1B19; padding: 15px; text-align: center;">
    <p style="color: #CECECE; margin: 0; font-size: 12px;">Palacio Fitness - Gimnasio exclusivo para mujeres</p>
  </div>
</div>`;

  // Generar mensaje de WhatsApp segun estado
  let whatsappText = '';
  switch (status) {
    case 'APPROVED':
      whatsappText = `\u2705 *Palacio Fitness - Pago Confirmado*\n\nHola! Tu pago por *${amountFormatted}* ha sido *aprobado* exitosamente.\n\nReferencia: ${reference}\n\nGracias por tu pago. \u00a1Te esperamos en el gym! \uD83D\uDCAA\n\nSi tienes alguna duda, escr\u00edbenos por este chat.`;
      break;
    case 'DECLINED':
      whatsappText = `\u274C *Palacio Fitness - Pago Rechazado*\n\nHola, tu pago por *${amountFormatted}* fue *rechazado* por la entidad financiera.\n\nReferencia: ${reference}\n\nPor favor intenta nuevamente o usa otro m\u00e9todo de pago en:\nhttps://fitness.ibonpalacio.com/pagos\n\nSi necesitas ayuda, escr\u00edbenos.`;
      break;
    case 'PENDING':
      whatsappText = `\u23F3 *Palacio Fitness - Pago Pendiente*\n\nHola, tu pago por *${amountFormatted}* est\u00e1 *pendiente* de confirmaci\u00f3n.\n\nReferencia: ${reference}\n\nTe notificaremos cuando se confirme. Si tienes dudas, escr\u00edbenos.`;
      break;
    case 'VOIDED':
      whatsappText = `\uD83D\uDEAB *Palacio Fitness - Pago Anulado*\n\nHola, tu pago por *${amountFormatted}* ha sido *anulado*.\n\nReferencia: ${reference}\n\nSi no solicitaste esta anulaci\u00f3n, por favor cont\u00e1ctanos.`;
      break;
    case 'ERROR':
      whatsappText = `\u26A0\uFE0F *Palacio Fitness - Error en Pago*\n\nHola, hubo un *error* procesando tu pago por *${amountFormatted}*.\n\nReferencia: ${reference}\n\nPor favor intenta nuevamente en:\nhttps://fitness.ibonpalacio.com/pagos\n\nSi el problema persiste, escr\u00edbenos.`;
      break;
    default:
      whatsappText = `\u2753 *Palacio Fitness - Actualizaci\u00f3n de Pago*\n\nHola, tu pago por *${amountFormatted}* tiene estado: *${status}*.\n\nReferencia: ${reference}\n\nSi tienes dudas, escr\u00edbenos.`;
  }

  results.push({
    json: {
      transactionId,
      reference,
      status,
      amountInCents,
      amountFormatted,
      customerEmail,
      customerPhone,
      paymentMethod,
      currency,
      sentAt,
      statusLabel: statusInfo.label,
      emailSubject,
      emailBody,
      whatsappText,
      clientEmailSubject: `${statusInfo.emoji} Tu pago en Palacio Fitness - ${statusInfo.verb}`,
      clientEmailBody: `<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;"><div style="background: #1C1B19; padding: 30px; text-align: center;"><h1 style="color: #FCD462; margin: 0; font-size: 28px;">Palacio Fitness</h1><p style="color: #CECECE; margin: 8px 0 0; font-size: 14px;">Gimnasio exclusivo para mujeres</p></div><div style="padding: 30px; background: #ffffff;"><div style="text-align: center; margin-bottom: 25px;"><span style="font-size: 48px;">${statusInfo.emoji}</span><h2 style="color: #333; margin: 10px 0 5px;">Pago ${statusInfo.verb}</h2><p style="color: #666; font-size: 28px; font-weight: bold; margin: 5px 0;">${amountFormatted}</p></div><div style="background: #f8f8f8; border-radius: 8px; padding: 20px; margin: 20px 0;"><table style="width: 100%; border-collapse: collapse;"><tr><td style="padding: 8px 0; color: #888; font-size: 13px;">Referencia</td><td style="padding: 8px 0; text-align: right; color: #333; font-size: 13px;">${reference}</td></tr><tr><td style="padding: 8px 0; color: #888; font-size: 13px;">M\u00e9todo</td><td style="padding: 8px 0; text-align: right; color: #333; font-size: 13px;">${paymentMethod}</td></tr><tr><td style="padding: 8px 0; color: #888; font-size: 13px;">Fecha</td><td style="padding: 8px 0; text-align: right; color: #333; font-size: 13px;">${sentAt ? new Date(sentAt).toLocaleString('es-CO', { timeZone: 'America/Bogota' }) : 'N/A'}</td></tr></table></div>${status === 'APPROVED' ? '<p style="color: #333; text-align: center;">Gracias por tu pago. \u00a1Te esperamos en el gym! \uD83D\uDCAA</p>' : status === 'DECLINED' ? '<p style="color: #333; text-align: center;">Tu pago fue rechazado. Por favor intenta con otro m\u00e9todo de pago.</p>' : status === 'PENDING' ? '<p style="color: #333; text-align: center;">Tu pago est\u00e1 pendiente de confirmaci\u00f3n. Te notificaremos cuando se procese.</p>' : '<p style="color: #333; text-align: center;">Si tienes dudas sobre tu pago, cont\u00e1ctanos.</p>'}<p style="text-align: center; margin-top: 25px;"><a href="https://fitness.ibonpalacio.com" style="background: #FCD462; color: #1C1B19; padding: 12px 30px; text-decoration: none; border-radius: 5px; font-weight: bold;">Ir a Palacio Fitness</a></p></div><div style="background: #1C1B19; padding: 20px; text-align: center;"><p style="color: #888; margin: 0; font-size: 12px;">Palacio Fitness - Laureles, Medell\u00edn</p><p style="color: #666; margin: 5px 0 0; font-size: 11px;">Este correo fue enviado autom\u00e1ticamente. No responder.</p></div></div>`
    }
  });
}

return results;
